  /* ---------------- 行 → 结构 ---------------- */
  function rowsToMap(rows) {
    const geo = {}, spots = {};
    rows.forEach(([name, cat, lat, lng, visitMin, tags, intro]) => {
      geo[name] = { lat, lng, source: GEO_NOTE, coordinateSystem: 'WGS84', note: '景点参考位置，非入口导航' };
      spots[name] = { cat, intro, tags: tags.split('|').filter(Boolean), visitMin };
    });
    return { geo, spots };
  }
  const EXPANSIONS = {
    '北京': rowsToMap(BEIJING),
    '上海': rowsToMap(SHANGHAI),
    '广州': rowsToMap(GUANGZHOU),
    '杭州': rowsToMap(HANGZHOU),
    '成都': rowsToMap(CHENGDU),
    '威海': rowsToMap(WEIHAI)
  };

